<?php
declare(strict_types=1);
namespace Babanoell\Auth\Administration;
use Babanoell\Auth\Support\IdGeneratorInterface; use DateTimeImmutable; use DateTimeZone; use PDO; use RuntimeException; use Throwable;
final class AccessDirectory {
 public function __construct(private readonly PDO $pdo,private readonly IdGeneratorInterface $ids){}
 public function organizations():array{$rows=$this->pdo->query("SELECT o.*, (SELECT COUNT(*) FROM branches b WHERE b.organization_id=o.id AND b.status='active') AS branch_count FROM organizations o ORDER BY o.status='active' DESC,o.name")->fetchAll(PDO::FETCH_ASSOC);return['items'=>$rows];}
 public function branches(?string $org=null):array{$org=trim((string)$org);if($org!==''){$s=$this->pdo->prepare("SELECT b.*,o.name AS organization_name FROM branches b JOIN organizations o ON o.id=b.organization_id WHERE b.organization_id=:org ORDER BY b.status='active' DESC,b.name");$s->execute([':org'=>$org]);}else{$s=$this->pdo->query("SELECT b.*,o.name AS organization_name FROM branches b JOIN organizations o ON o.id=b.organization_id ORDER BY o.name,b.status='active' DESC,b.name");}return['items'=>$s->fetchAll(PDO::FETCH_ASSOC)];}
 public function createOrganization(array$in,string$actor):array{$code=strtolower(trim((string)($in['code']??'')));$name=trim((string)($in['name']??''));$type=strtolower(trim((string)($in['organization_type']??'business')));if(!preg_match('/^[a-z0-9][a-z0-9_.-]{1,79}$/',$code))throw new RuntimeException('کد سازمان معتبر نیست.');if($name===''||mb_strlen($name)>190)throw new RuntimeException('نام سازمان معتبر نیست.');if(!preg_match('/^[a-z0-9_.-]{2,32}$/',$type))throw new RuntimeException('نوع سازمان معتبر نیست.');$id=$this->ids->generate();$s=$this->pdo->prepare("INSERT INTO organizations(id,code,name,organization_type,status) VALUES(:id,:code,:name,:type,'active')");$s->execute([':id'=>$id,':code'=>$code,':name'=>$name,':type'=>$type]);return['id'=>$id,'code'=>$code,'name'=>$name,'organization_type'=>$type,'status'=>'active'];}
 public function createBranch(string$org,array$in,string$actor):array{$this->assertOrganization($org);$code=strtolower(trim((string)($in['code']??'')));$name=trim((string)($in['name']??''));if(!preg_match('/^[a-z0-9][a-z0-9_.-]{1,79}$/',$code)||$name===''||mb_strlen($name)>190)throw new RuntimeException('اطلاعات شعبه معتبر نیست.');$id=$this->ids->generate();$s=$this->pdo->prepare("INSERT INTO branches(id,organization_id,code,name,status) VALUES(:id,:org,:code,:name,'active')");$s->execute([':id'=>$id,':org'=>$org,':code'=>$code,':name'=>$name]);return['id'=>$id,'organization_id'=>$org,'code'=>$code,'name'=>$name,'status'=>'active'];}
 public function userAccess(string$user):array{$this->assertUser($user);$u=$this->pdo->prepare('SELECT id,display_name,mobile,email,status FROM users WHERE id=:u LIMIT 1');$u->execute([':u'=>$user]);$m=$this->pdo->prepare('SELECT m.organization_id,m.branch_id,m.title,m.membership_status,m.is_primary,o.name AS organization_name,o.code AS organization_code,b.name AS branch_name,b.code AS branch_code FROM user_organization_memberships m JOIN organizations o ON o.id=m.organization_id LEFT JOIN branches b ON b.id=m.branch_id WHERE m.user_id=:u ORDER BY m.is_primary DESC,o.name');$m->execute([':u'=>$user]);$g=$this->pdo->prepare("SELECT id,scope_type,scope_id,effect,expires_at FROM authorization_scope_grants WHERE user_id=:u ORDER BY scope_type,scope_id,effect");$g->execute([':u'=>$user]);return['user'=>$u->fetch(PDO::FETCH_ASSOC),'memberships'=>$m->fetchAll(PDO::FETCH_ASSOC),'grants'=>$g->fetchAll(PDO::FETCH_ASSOC)];}
 public function replaceMemberships(string$user,array$items,string$actor):array{$this->assertUser($user);if(count($items)>100)throw new RuntimeException('تعداد عضویت‌های ارسالی بیش از حد مجاز است.');$normalized=[];$primarySeen=false;foreach($items as$x){if(!is_array($x))continue;$org=trim((string)($x['organization_id']??''));if($org==='')continue;$this->assertOrganization($org);$branch=trim((string)($x['branch_id']??''));if($branch!=='')$this->assertBranchInOrganization($branch,$org);$primary=!$primarySeen&&filter_var($x['is_primary']??false,FILTER_VALIDATE_BOOL);if($primary)$primarySeen=true;$normalized[$org]=['org'=>$org,'branch'=>$branch!==''?$branch:null,'title'=>mb_substr(trim((string)($x['title']??'')),0,190)?:null,'primary'=>$primary];}
  $this->pdo->beginTransaction();try{$this->pdo->prepare('DELETE FROM user_organization_memberships WHERE user_id=:u')->execute([':u'=>$user]);$ins=$this->pdo->prepare("INSERT INTO user_organization_memberships(user_id,organization_id,branch_id,title,membership_status,is_primary,created_by_user_id) VALUES(:u,:o,:b,:t,'active',:p,:a)");foreach($normalized as$x)$ins->execute([':u'=>$user,':o'=>$x['org'],':b'=>$x['branch'],':t'=>$x['title'],':p'=>$x['primary']?1:0,':a'=>$actor]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->userAccess($user);}
 public function replaceGrants(string$user,array$items,string$actor):array{$this->assertUser($user);if(count($items)>250)throw new RuntimeException('تعداد دامنه‌های دسترسی بیش از حد مجاز است.');$allowed=['global','organization','branch','merchant','loan_request'];$normalized=[];foreach($items as$x){if(!is_array($x))continue;$type=strtolower(trim((string)($x['scope_type']??'')));$effect=strtolower(trim((string)($x['effect']??'allow')));$scope=trim((string)($x['scope_id']??''));if(!in_array($type,$allowed,true)||!in_array($effect,['allow','deny'],true))throw new RuntimeException('دامنه دسترسی معتبر نیست.');if($type==='global')$scope='*';if($scope===''||mb_strlen($scope)>190)throw new RuntimeException('شناسه دامنه دسترسی معتبر نیست.');if($type==='organization')$this->assertOrganization($scope);if($type==='branch')$this->assertBranch($scope);$expires=$this->normalizeExpiry($x['expires_at']??null);$key=$type.'|'.$scope.'|'.$effect;$normalized[$key]=['type'=>$type,'scope'=>$scope,'effect'=>$effect,'expires'=>$expires];}
  $this->pdo->beginTransaction();try{$this->pdo->prepare('DELETE FROM authorization_scope_grants WHERE user_id=:u')->execute([':u'=>$user]);$ins=$this->pdo->prepare('INSERT INTO authorization_scope_grants(id,user_id,scope_type,scope_id,effect,expires_at,created_by_user_id) VALUES(:id,:u,:t,:s,:e,:x,:a)');foreach($normalized as$x)$ins->execute([':id'=>$this->ids->generate(),':u'=>$user,':t'=>$x['type'],':s'=>$x['scope'],':e'=>$x['effect'],':x'=>$x['expires'],':a'=>$actor]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->userAccess($user);}
 private function normalizeExpiry(mixed$v):?string{$v=trim((string)($v??''));if($v==='')return null;try{$d=new DateTimeImmutable($v);return$d->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s.u');}catch(Throwable){throw new RuntimeException('تاریخ انقضای دسترسی معتبر نیست.');}}
 private function assertUser(string$id):void{$s=$this->pdo->prepare('SELECT 1 FROM users WHERE id=:id');$s->execute([':id'=>$id]);if(!$s->fetchColumn())throw new RuntimeException('کاربر پیدا نشد.');}
 private function assertOrganization(string$id):void{$s=$this->pdo->prepare("SELECT 1 FROM organizations WHERE id=:id AND status='active'");$s->execute([':id'=>$id]);if(!$s->fetchColumn())throw new RuntimeException('سازمان فعال پیدا نشد.');}
 private function assertBranch(string$id):void{$s=$this->pdo->prepare("SELECT 1 FROM branches WHERE id=:id AND status='active'");$s->execute([':id'=>$id]);if(!$s->fetchColumn())throw new RuntimeException('شعبه فعال پیدا نشد.');}
 private function assertBranchInOrganization(string$branch,string$org):void{$s=$this->pdo->prepare("SELECT 1 FROM branches WHERE id=:b AND organization_id=:o AND status='active'");$s->execute([':b'=>$branch,':o'=>$org]);if(!$s->fetchColumn())throw new RuntimeException('شعبه انتخاب‌شده متعلق به سازمان انتخاب‌شده نیست.');}
}
